-- =============================================================================
-- nba_roster_adjusted_registry.sql — register the NBA Roster-Adjusted
-- Projection (NBA-ROSTER-ADJ v0.1) as EXPERIMENTAL in the research
-- registry, before any holdout evaluation. README §NBA roster and injury layer.
--
-- GENERATED by tools/nba/build_roster_adjusted_registry_sql.js from
-- nba/research/roster_adjusted/registration.json (content sha256
-- 52f4af15a457c9a551f86fb6b8ad23fd83012906430610eb46263159c26378bf). Do not edit by hand.
--
-- WHAT IT DOES. One research_models row (EXPERIMENTAL, provenance T3) and one
-- research_model_versions row (version 0.1, EXPERIMENTAL) carrying the
-- objective, the holdout window, the minimum sample, the primary metric, the
-- promotion criteria (C1 margin MAE, C2 total MAE, C3 CLV, C4 calibration
-- guard, C5 coverage guard), the forking-paths disclosure (one candidate
-- tried, none evaluated) and the full specification (status-to-play
-- probabilities, minutes rule, impact measure), written in whatever form the
-- live columns take. Then the version row is named in
-- public.nba_injury_config (roster_model_key / _version / _version_ref):
-- supabase/nba_injury_layer.sql refuses any projection that names another.
--
-- WHAT IT DOES NOT DO. No research_model_results row (there is no result, so
-- every reader shows Experimental). No change to a registered row. Nothing
-- here touches the baseline projection, a ranking or a grade.
--
-- REQUIRES supabase/nba_injury_layer.sql and the research registry.
-- CONVENTION (supabase/README.md): idempotent, additive, pasted into the SQL
-- editor, no psql meta-commands, ends in a report. Safe to run again.
-- =============================================================================

do $req$ begin
  if to_regclass('public.research_models') is null or to_regclass('public.research_model_versions') is null then
    raise exception 'the research registry (public.research_models, public.research_model_versions) is not in this database: nothing was registered';
  end if;
  if to_regclass('public.nba_injury_config') is null then raise exception 'apply supabase/nba_injury_layer.sql first'; end if;
end $req$;

-- helpers for this session only (pg_temp: gone when the editor's session ends)
create or replace function pg_temp.edr_has(p_rel regclass, p_names text[]) returns text
language sql stable as $f$
  select u.n from unnest(p_names) with ordinality u(n, i)
   where exists (select 1 from pg_attribute a where a.attrelid = p_rel and a.attname = u.n and a.attnum > 0 and not a.attisdropped)
   order by u.i limit 1
$f$;
create or replace function pg_temp.edr_typ(p_rel regclass, p_col text) returns text
language sql stable as $f$
  select format_type(a.atttypid, a.atttypmod) from pg_attribute a where a.attrelid = p_rel and a.attname = p_col and a.attnum > 0 and not a.attisdropped
$f$;
-- an enum column takes the live label whose lower case is wanted; a text column takes the first wanted value
create or replace function pg_temp.edr_label(p_rel regclass, p_col text, p_wanted text[]) returns text
language plpgsql stable as $f$
declare t oid; l text;
begin
  select a.atttypid into t from pg_attribute a where a.attrelid = p_rel and a.attname = p_col and a.attnum > 0;
  if exists (select 1 from pg_type where oid = t and typtype = 'e') then
    select e.enumlabel into l from pg_enum e where e.enumtypid = t and lower(e.enumlabel) = any (p_wanted)
     order by array_position(p_wanted, lower(e.enumlabel)) limit 1;
    if l is null then
      raise exception 'research registry: %.% is an enum with no label for % (its labels: %) — nothing was registered', p_rel, p_col, p_wanted[1],
        (select string_agg(enumlabel, ', ' order by enumsortorder) from pg_enum where enumtypid = t);
    end if;
    return l;
  end if;
  return p_wanted[1];
end $f$;
-- a value shaped for the column it lands in
create or replace function pg_temp.edr_val(p_rel regclass, p_col text, p_text text, p_json jsonb, p_range jsonb) returns jsonb
language plpgsql stable as $f$
declare t text := pg_temp.edr_typ(p_rel, p_col);
begin
  if t is null then return null; end if;
  if t like '%range' then return case when p_range is null or jsonb_typeof(p_range) <> 'array' then 'null'::jsonb
    else to_jsonb('[' || (p_range ->> 0) || ',' || (p_range ->> 1) || ')') end; end if;
  if t = 'date' then return case when p_range is null or jsonb_typeof(p_range) <> 'array' then 'null'::jsonb else p_range -> 0 end; end if;
  if t in ('jsonb', 'json') then return coalesce(p_json, to_jsonb(p_text)); end if;
  if t in ('integer', 'bigint', 'smallint', 'numeric') then return case when jsonb_typeof(p_json) = 'number' then p_json else 'null'::jsonb end; end if;
  if t = 'boolean' then return case when jsonb_typeof(p_json) = 'boolean' then p_json else 'null'::jsonb end; end if;
  return to_jsonb(coalesce(p_text, p_json #>> '{}', p_json::text));
end $f$;
-- insert the listed columns only (so every other column keeps its own default);
-- refuse, by name, a required column with nothing to put in it
create or replace function pg_temp.edr_insert(p_rel regclass, p_vals jsonb, p_ret text) returns text
language plpgsql as $f$
declare cols text; missing text; out_ text;
begin
  select string_agg(quote_ident(k), ', ') into cols from jsonb_object_keys(p_vals) k;
  select string_agg(a.attname::text, ', ') into missing from pg_attribute a
   where a.attrelid = p_rel and a.attnum > 0 and not a.attisdropped and a.attnotnull and not a.atthasdef
     and a.attidentity = '' and a.attgenerated = '' and not (p_vals ? a.attname::text);
  if missing is not null then
    raise exception 'research registry: % requires % and this file has nothing to put there — nothing was registered (map it in tools/nba/build_roster_adjusted_registry_sql.js)', p_rel, missing;
  end if;
  execute format('insert into %s (%s) select %s from jsonb_populate_record(null::%s, $1) returning %I::text', p_rel, cols, cols, p_rel, p_ret) into out_ using p_vals;
  return out_;
end $f$;

begin;

do $reg$
declare
  S jsonb := $nbareg${"schema":"edgedesk_research_registration_v1","model_key":"NBA-ROSTER-ADJ","name":"NBA Roster-Adjusted Projection","version":"0.1","status":"EXPERIMENTAL","provenance":"T3","provenance_label":"EdgeDesk research","sport":"NBA","registered_at":"2026-10-21","hypothesis":"Pricing each game with the current roster and the league's injury report — the minutes-weighted impact change applied at full weight to the team ratings — projects final margins and totals more accurately than the baseline, which prices each team's previous game's rotation (last season's closing game at a season's start).","objective":"Lower the error of EdgeDesk's pregame NBA projections of final margin and final total by replacing the baseline's carried rotation with current rosters and the official injury report, without worse win-probability calibration, and with a detection-time edge against the market that tracks closing-line value at least as well as the baseline's.","primary_metric":"Paired difference in mean absolute error of the expected final margin (adjusted minus baseline), regular-season holdout games; then the same for the expected final total.","unit":"One NBA regular-season game in the holdout window with (a) a baseline row in nba/ledger/<season>.jsonl recorded before tip and (b) an nba_adjusted_projection_snapshots row with status OK, computed before tip from an official-report snapshot (source nba_official). Each side's last pre-tip value is the one evaluated.","baseline":"The published EdgeDesk NBA price (edgedesk_nba_v1, the walk-forward's chosen model on the projected-availability track), unchanged, as the ledger froze it before tip.","training_window":"None fitted. Every number in the transform is fixed in advance (spec below); the player impact (RAPM) and expected minutes are the baseline engine's own, point in time.","validation_window":"None. There is no tuning step to validate.","holdout_window":"Regular-season games tipping from 2026-10-22 through the end of the 2026-27 regular season, evaluated once after the last regular-season game. 2026-10-21 is excluded: its Hornets–Nets game was examined at registration (see forking_paths.data_already_seen).","machine":{"window_dates":{"training":null,"validation":null,"holdout":["2026-10-22","2027-04-12"]},"window_note":"[from, to): Eastern dates of the games inside each window","minimum_sample":600,"version":"0.1","status":"EXPERIMENTAL","provenance":"T3"},"minimum_sample":{"paired_games_holdout":600,"games_with_market_captures_for_clv":300,"note":"Below 600 paired games the holdout is reported descriptively and no result row is written. The CLV criterion needs 300 holdout games with an NBA price captured at the snapshot's time and a closing price; NBA prices are not captured today (repository variable NBA_PRICES off), so until they are, that criterion is NOT EVALUABLE and the model cannot pass."},"promotion_criteria":{"decision_rule":"passed = true only if, on the holdout, every criterion below holds. A criterion that cannot be evaluated (too few games, no market captures) is not met. Evaluated once, after the regular season; no interim look decides anything. Passing makes the model eligible for promotion; a person promotes it, through a validation report that compares it with the frozen baseline.","criteria":[{"id":"C1_MARGIN_MAE","rule":"Mean absolute error of the expected final margin: adjusted < baseline, and the 95% upper bound of the paired difference (adjusted - baseline), date-blocked bootstrap with 2000 resamples, is below 0."},{"id":"C2_TOTAL_MAE","rule":"Mean absolute error of the expected final total: adjusted < baseline, with the same test."},{"id":"C3_CLV","rule":"Detection-time edge against the market correlates with positive CLV at least as well as the baseline's: Spearman correlation between (fair spread - market spread at the snapshot's time, signed toward the side the model favours) and spread CLV (closing spread - detection spread, signed the same way). Adjusted correlation >= baseline correlation, and the 95% bootstrap lower bound of their difference > -0.05. Needs 300 games with captured prices."},{"id":"C4_CALIBRATION_GUARD","rule":"Win-probability log loss is not worse: adjusted - baseline <= +0.005 on the paired games."},{"id":"C5_COVERAGE_GUARD","rule":"The model publishes (status OK, not WITHHELD) for at least 80% of holdout games; withheld games and their reasons are reported."}],"family_correction":"C1 and C2 are both required (an intersection test): no correction is applied, and no criterion is reported as a pass on its own."},"forking_paths":{"candidates_tried":[{"version":"0.1","status_mapping":{"OUT":0,"DOUBTFUL":0.25,"QUESTIONABLE":0.5,"PROBABLE":0.9,"AVAILABLE":1,"UNKNOWN":0.5},"rating_coefficient":1,"minutes":"depth chart on expected minutes (EWM + preseason prior), exact expectation over statuses","reference_rotation":"the baseline engine's full-strength reference (every player in the team's last ten games, at his usual minutes)","evaluated_against_outcomes":false}],"alternatives_considered_not_tried":["Feeding the new availability through the baseline's own learned availability features (the slate's existing roster scenario): it moves Hornets–Nets by under one point, because the stack learned a small weight for availability. Rejected on structure before any evaluation; it remains on the card as the slate's own scenario.","A rating coefficient below 1 (shrinking the impact change).","Other status mappings (Questionable 0.4 or 0.6; Doubtful 0.1; Probable 0.95).","Proportional redistribution over the whole roster instead of the depth chart.","A reference rotation of each team's observed minutes over its last 20 games.","Box-score impact (BPM-style) or a third-party metric instead of EdgeDesk's RAPM."],"choice_and_reason":"One candidate, written before any evaluation: full weight because the hypothesis is structural (minutes x impact is what the team rating should move by); the mapping's values are round conventional estimates, not fitted; the depth chart because an absent starter's minutes go to the next players in the rotation, not to every rostered player; the reference is the baseline engine's own, so the reset and the shift stand on one definition.","data_already_seen":"At registration: the 2025-26 RAPM values and expected minutes the baseline already publishes; the Hornets–Nets 2026-10-21 market line (Brooklyn -1.5) and this model's output for that game, computed for the acceptance check from the statuses the product owner provided (Brooklyn -2.5). No other game's outcome or market line was compared with this model. That date is excluded from the holdout.","comparisons_made":1,"stopping_rule":"Fixed horizon: the holdout is read once, after the last regular-season game of 2026-27."},"spec":{"transform":"adjusted mean margin = neutral mean margin + sum over home players of (A_i - R_i) / 48 * (o_i + d_i) * pace / 100 - the same over away players; adjusted mean total = neutral mean total + sum over all players of (A_i - R_i) / 48 * (o_i - d_i) * pace / 100. R_i: the reference rotation's minutes; A_i: tonight's expected minutes; o_i, d_i: RAPM offence and defence per 100 possessions (positive = good); pace: the baseline's expected possessions. The neutral means are the baseline's chosen model re-priced with its availability features set to each team's full-strength reference (adj_proj 0). The adjusted means are priced by the baseline's own distribution (nba/model/distribution.js) with its own standard-deviation rule; nothing else of the baseline changes.","play_probability":{"OUT":0,"DOUBTFUL":0.25,"QUESTIONABLE":0.5,"PROBABLE":0.9,"AVAILABLE":1,"UNKNOWN":0.5},"minutes":{"team_minutes":240,"max_minutes":40,"ewm_weight_games":4,"preseason_weight_games":4,"preseason_fade_games":10,"rookie_minutes":10,"max_uncertain":12},"impact":{"measure":"edgedesk_rapm_v1","tier":"T2","prior_o":-0.5,"prior_d":-0.5},"rating_coefficient":1,"sanity":{"max_abs_margin_shift":25,"max_abs_total_shift":30},"withheld_when":["no injury report, or the game is not on the latest report","a team has not submitted its report (NOT YET SUBMITTED)","a listed player (not AVAILABLE) cannot be matched to a rostered player","the report lists a player the roster capture has on another team","a team has no roster capture","more than 12 players on a team with an uncertain status","the shift exceeds the sanity bound"],"code":"nba/injury/core.js nbaRosterAdjust (copied verbatim into supabase/functions/nba_injury_sync/index.ts)","inputs":"nba/roster_inputs.json (nba/build_slate.js), public.nba_roster_snapshots, public.nba_injury_report_snapshots"},"result":null,"content_sha256":"52f4af15a457c9a551f86fb6b8ad23fd83012906430610eb46263159c26378bf"}$nbareg$::jsonb;
  m regclass := 'public.research_models';
  v regclass := 'public.research_model_versions';
  mv jsonb; vv jsonb; mach jsonb := S -> 'machine';
  kcol text; ncol text; refcol text; fkcol text; vcol text; vid text; c text; ref text; vref text; have boolean;
  pairs text[][] := array[
    array['training_window', 'train_window', 'training_period', 'training'],
    array['validation_window', 'valid_window', 'validation_period', 'validation'],
    array['holdout_window', 'holdout_period', 'holdout', 'test_window']];
  wkeys text[] := array['training', 'validation', 'holdout'];
  i int;
begin
  kcol := pg_temp.edr_has(m, array['model_key', 'key', 'model_name', 'model', 'slug', 'code', 'name']);
  if kcol is null then raise exception 'research registry: research_models has no key column (model_key, key, model_name, model, slug, code or name) — nothing was registered'; end if;
  select a.attname::text, ra.attname::text into fkcol, refcol
    from pg_constraint k
    join pg_attribute a on a.attrelid = k.conrelid and a.attnum = k.conkey[1]
    join pg_attribute ra on ra.attrelid = k.confrelid and ra.attnum = k.confkey[1]
   where k.contype = 'f' and k.conrelid = v and k.confrelid = m limit 1;
  if fkcol is null then
    fkcol := pg_temp.edr_has(v, array['model_key', 'model_id', 'research_model_id', 'model']);
    refcol := case when fkcol in ('model_id', 'research_model_id') then pg_temp.edr_has(m, array['id', 'model_id']) else kcol end;
  end if;
  if fkcol is null or refcol is null then raise exception 'research registry: cannot tell how research_model_versions points at research_models — nothing was registered'; end if;
  vcol := pg_temp.edr_has(v, array['version', 'model_version', 'version_label', 'semver', 'label']);
  vid := pg_temp.edr_has(v, array['id', 'version_id', 'model_version_id']);

  execute format('select %I::text from %s where %I::text = $1 limit 1', refcol, m, kcol) into ref using S ->> 'model_key';
  if ref is null then
    mv := jsonb_build_object(kcol, S ->> 'model_key');
    ncol := pg_temp.edr_has(m, array['name', 'title', 'display_name', 'label']);
    if ncol is not null and ncol <> kcol then mv := mv || jsonb_build_object(ncol, S ->> 'name'); end if;
    foreach c in array array['title', 'display_name'] loop
      if c <> kcol and pg_temp.edr_has(m, array[c]) is not null and not (mv ? c) then mv := mv || jsonb_build_object(c, S ->> 'name'); end if;
    end loop;
    c := pg_temp.edr_has(m, array['sport', 'league']); if c is not null then mv := mv || jsonb_build_object(c, 'NBA'); end if;
    c := pg_temp.edr_has(m, array['sport_key']); if c is not null then mv := mv || jsonb_build_object(c, 'basketball_nba'); end if;
    c := pg_temp.edr_has(m, array['status', 'model_status', 'maturity']); if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_label(m, c, array['experimental'])); end if;
    c := pg_temp.edr_has(m, array['provenance', 'evidence_provenance', 'tier', 'evidence_tier']);
    if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_label(m, c, array['t3', 'research_model', 'research', 'model'])); end if;
    c := pg_temp.edr_has(m, array['objective', 'goal']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'objective'); end if;
    c := pg_temp.edr_has(m, array['hypothesis']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'hypothesis'); end if;
    c := pg_temp.edr_has(m, array['description', 'summary']); if c is not null then mv := mv || jsonb_build_object(c, S ->> 'hypothesis'); end if;
    c := pg_temp.edr_has(m, array['family', 'category', 'module', 'domain']); if c is not null then mv := mv || jsonb_build_object(c, 'nba_roster_injury'); end if;
    c := pg_temp.edr_has(m, array['owner', 'created_by', 'registered_by']); if c is not null then mv := mv || jsonb_build_object(c, (S ->> 'registered_at') || ' preregistration (EdgeDesk research)'); end if;
    c := pg_temp.edr_has(m, array['metadata', 'meta', 'spec', 'details', 'config']);
    if c is not null then mv := mv || jsonb_build_object(c, pg_temp.edr_val(m, c, null, S, null)); end if;
    ref := pg_temp.edr_insert(m, mv, refcol);
    raise notice 'research registry: % registered', S ->> 'model_key';
  else
    raise notice 'research registry: % was already registered and is left as it is', S ->> 'model_key';
  end if;

  if vcol is not null then
    execute format('select exists (select 1 from %s where %I::text = $1 and %I::text = $2)', v, fkcol, vcol) into have using ref, S ->> 'version';
  else
    execute format('select exists (select 1 from %s where %I::text = $1)', v, fkcol) into have using ref;
  end if;
  if not have then
    vv := jsonb_build_object(fkcol, ref);
    if vcol is not null then vv := vv || jsonb_build_object(vcol, S ->> 'version'); end if;
    c := pg_temp.edr_has(v, array['status', 'model_status', 'maturity']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['experimental'])); end if;
    c := pg_temp.edr_has(v, array['provenance', 'evidence_provenance', 'tier']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_label(v, c, array['t3', 'research_model', 'research', 'model'])); end if;
    for i in 1 .. 3 loop
      c := pg_temp.edr_has(v, pairs[i:i][1:4]::text[]);
      if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> (wkeys[i] || '_window'),
        jsonb_build_object('from', mach -> 'window_dates' -> wkeys[i] -> 0, 'to', mach -> 'window_dates' -> wkeys[i] -> 1, 'description', S ->> (wkeys[i] || '_window')),
        mach -> 'window_dates' -> wkeys[i])); end if;
    end loop;
    c := pg_temp.edr_has(v, array['objective', 'goal']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'objective', null, null)); end if;
    c := pg_temp.edr_has(v, array['hypothesis']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'hypothesis', null, null)); end if;
    c := pg_temp.edr_has(v, array['min_sample', 'minimum_sample', 'min_n', 'sample_target']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, (S -> 'minimum_sample')::text,
      case when pg_temp.edr_typ(v, c) in ('jsonb', 'json') then S -> 'minimum_sample' else mach -> 'minimum_sample' end, null)); end if;
    c := pg_temp.edr_has(v, array['success_metric', 'primary_metric', 'metric']); if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S ->> 'primary_metric', null, null)); end if;
    c := pg_temp.edr_has(v, array['promotion_criteria', 'decision_rule', 'criteria', 'success_criteria']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, S -> 'promotion_criteria' ->> 'decision_rule', S -> 'promotion_criteria', null)); end if;
    c := pg_temp.edr_has(v, array['forking_paths', 'forking_paths_disclosure', 'disclosure', 'garden_of_forking_paths']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'forking_paths', null)); end if;
    c := pg_temp.edr_has(v, array['spec', 'metadata', 'meta', 'params', 'config', 'details', 'definition', 'protocol']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c, null, S -> 'spec' || jsonb_build_object('content_sha256', S ->> 'content_sha256', 'registration', 'nba/research/roster_adjusted/registration.json'), null)); end if;
    c := pg_temp.edr_has(v, array['notes', 'description']);
    if c is not null then vv := vv || jsonb_build_object(c, pg_temp.edr_val(v, c,
      'Preregistered ' || (S ->> 'registered_at') || ': nba/research/roster_adjusted/registration.json sha256 ' || (S ->> 'content_sha256') || '. No result until a validation report writes one.', null, null)); end if;
    perform pg_temp.edr_insert(v, vv, fkcol);
  end if;

  -- the version row every stored projection must name
  if vid is not null and vcol is not null then
    execute format('select %I::text from %s where %I::text = $1 and %I::text = $2 limit 1', vid, v, fkcol, vcol) into vref using ref, S ->> 'version';
  end if;
  vref := coalesce(vref, ref || ':' || (S ->> 'version'));
  insert into public.nba_injury_config (key, value, note) values
    ('roster_model_key', S ->> 'model_key', 'research_models key of the Roster-Adjusted Projection'),
    ('roster_model_version', S ->> 'version', 'the registered version the sync prices'),
    ('roster_model_version_ref', vref, 'research_model_versions row (as text); every projection must name it'),
    ('roster_model_registration_sha256', S ->> 'content_sha256', 'nba/research/roster_adjusted/registration.json')
  on conflict (key) do update set value = excluded.value, updated_at = now();
end $reg$;

commit;

-- THE REPORT: the model as research_model_current reads it, and the link the sync stamps. Every row should say ok.
create or replace function pg_temp.edr_report() returns table (piece text, state text)
language plpgsql as $f$
declare j jsonb; s text; p text;
begin
  if to_regclass('public.research_model_current') is not null then
    execute 'select to_jsonb(r) from public.research_model_current r where lower(coalesce(to_jsonb(r) ->> ''model_key'', to_jsonb(r) ->> ''key'', to_jsonb(r) ->> ''model_name'', to_jsonb(r) ->> ''model'', to_jsonb(r) ->> ''name'')) = lower($1) limit 1'
      into j using 'NBA-ROSTER-ADJ';
  end if;
  s := lower(coalesce(j ->> 'status', j ->> 'model_status', j ->> 'maturity', ''));
  p := coalesce(j ->> 'passed', 'null');
  piece := '1 NBA-ROSTER-ADJ is EXPERIMENTAL with no result';
  state := case when to_regclass('public.research_model_current') is null then 'CHECK THIS: research_model_current is not in this database'
                when j is null then 'CHECK THIS: not in research_model_current'
                when s <> 'experimental' then 'CHECK THIS: status reads ' || s
                when p = 'true' then 'CHECK THIS: a result row shows passed = true'
                else 'ok' end;
  return next;
  piece := '2 the sync stamps version 0.1 and its registry row';
  state := case when (select value from public.nba_injury_config where key = 'roster_model_version') = '0.1'
                 and (select value from public.nba_injury_config where key = 'roster_model_version_ref') is not null then 'ok' else 'CHECK THIS' end;
  return next;
end $f$;
select * from pg_temp.edr_report();
